#pragma once
#include <string>
#include <vector>

struct Package {
    std::string name, version, source, arch, manager;
};

struct Comment {
    // why | risk | version | action | source | caveat | note
    std::string tag;
    std::string text;
    // "llm:<model>" when generated by a model, "rule" when templated.
    std::string origin;
};

struct Advisory {
    std::string id;
    std::string source;
    std::string title;
    std::string url;
    std::string date;
    std::string body;
    std::vector<std::string> cves;
    std::string severity = "Unknown";
    std::string severity_raw;   // CVSS vector, when the source supplies one
    std::string fixed_hint;
    bool verified = false;      // true => came from a version-range database
    std::string pkg_hint;       // exact package this record resolved for
};

struct Finding {
    Package pkg;
    int score = 0;
    std::string confidence;     // High | Medium | Low
    std::string severity;
    std::string match_method;   // osv_version_range | name_title_match
    std::string fixed_version;
    std::vector<Comment> comments;
    std::vector<int> advisory_ids;
    std::string comment_model;  // empty when rule-based
};

struct ScanResult {
    std::vector<Package> packages;
    std::vector<Advisory> advisories;
    std::vector<Finding> findings;
    std::vector<std::string> notes;
    std::string distro_pretty;
    std::string ecosystem;
    int osv_records = 0;
    int llm_requests = 0;
    int llm_cache_hits = 0;
    int llm_failures = 0;
    int llm_suppressed = 0;
    int llm_fallbacks = 0;
};
